# 检查 sop.yaml 是否指定了 source_dir
python3 -c "
import yaml
try:
    sop = yaml.safe_load(open('sop.yaml'))
    for s in sop.get('pipeline', []):
        if s.get('stage') in ('wiki-build','wiki-build-direct'):
            sd = s.get('params',{}).get('source_dir','')
            if sd: print('--analysis-dir', sd)
            break
except Exception as e:
    print(f'# error: {e}')
" 2>/dev/null", "timeout": 10}
